package com.orderflow.notification.service;import static org.assertj.core.api.Assertions.assertThat;import com.orderflow.notification.domain.NotificationType;import com.orderflow.notification.provider.*;import org.junit.jupiter.api.Test;class NotificationSupportTest{@Test void templatesAreTrusted(){var t=new NotificationTemplateService().template(NotificationType.DELIVERY_OUT_FOR_DELIVERY);assertThat(t.title()).isEqualTo("Out for delivery");assertThat(t.message()).doesNotContain("address");}@Test void destinationsAreMasked(){DestinationMasker m=new DestinationMasker();assertThat(m.email("roshan@example.test")).isEqualTo("r***@example.test");assertThat(m.phone("+19990001234")).endsWith("1234").doesNotContain("999000");}@Test void simulatorsClassifyFailures(){var email=new SimulatorEmailNotificationSender();assertThat(email.send("success@example.test","t","m").result()).isEqualTo(SendResult.Result.SUCCESS);assertThat(email.send("temporary-failure@example.test","t","m").result()).isEqualTo(SendResult.Result.TEMPORARY_FAILURE);assertThat(email.send("permanent-failure@example.test","t","m").result()).isEqualTo(SendResult.Result.PERMANENT_FAILURE);var sms=new SimulatorSmsNotificationSender();assertThat(sms.send("+19990000001","m").result()).isEqualTo(SendResult.Result.TEMPORARY_FAILURE);}}
